// bench-aggregates.cpp
// Latency benchmarks for RollingSum::on_tick, built on Google Benchmark.
//
// Easiest: ./bench.sh            # build, run, compare against the last commit
// By hand (from src/feed-handler):
//   g++-14 -std=c++23 -O2 -march=native -DNDEBUG bench-aggregates.cpp -lbenchmark -lpthread -o ../../build/bench-aggregates
//   ../../build/bench-aggregates --benchmark_filter=path
//
// Three families. In all of them the "Time" column is nanoseconds per tick.
//
//   RollingSum/path/...     One path through on_tick per benchmark (see path_stream).
//                           The slowest row is the worst-case cost of the code itself.
//                           Each stream takes a single path, so the branch predictor is
//                           always right: these are best-case costs for each path.
//   RollingSum/corpus/...   The realistic tick stream from TickGenerator. Mean cost per
//                           tick, including mispredictions caused by the rare slow ticks.
//                           Counters give the number of ticks on each path.
//   RollingSum/percall/...  Times every single call and reports percentiles (ns, net of
//                           timer overhead). Its Time column includes the timer and is
//                           NOT the cost of on_tick. Only meaningful where the clock step
//                           is far below the cost of a call: fine on x86 (rdtsc), not on
//                           the ARM VM (41.67 ns step); the label says which.

#include <benchmark/benchmark.h>

#include "../rolling-sum.hpp"
#include "cycle-clock.hpp"
#include "tick-generator.hpp"

#include <algorithm>
#include <chrono>
#include <cstdint>
#include <cstdio>
#include <numeric>
#include <vector>

// ---------------------------------------------------------------------------
// The aggregate under test. Anything with these template parameters,
// on_tick(const Tick&) and get_sum() can be dropped in here.
// ---------------------------------------------------------------------------
template <std::size_t NBuckets, std::int64_t BucketNs>
using Agg = RollingSum<NBuckets, BucketNs>;

// ---------------------------------------------------------------------------
// Inputs. Built once, outside any timed loop.
// ---------------------------------------------------------------------------
static const std::vector<Tick>& corpus() {
    static const std::vector<Tick> c = TickGenerator::corpus(200'000);
    return c;
}

// A stream in which every tick takes the same path through a bucketed aggregate.
//   gap = -1  late ticks: the first tick jumps ahead, the rest fall in an older bucket
//   gap =  0  every tick lands in the current bucket
//   gap >= 1  every tick lands gap buckets after the previous one
//             (gap > nbuckets is the long-silence path)
static std::vector<Tick> path_stream(std::int64_t gap, std::int64_t bucket_ns) {
    constexpr std::int64_t kTicks = 16'384;
    std::vector<Tick> v;
    v.reserve(kTicks);
    for (std::int64_t i = 0; i < kTicks; ++i) {
        std::int64_t ts;
        if (gap < 0)       ts = (i == 0) ? 1000 * bucket_ns : i;
        else if (gap == 0) ts = i;
        else               ts = (i + 1) * gap * bucket_ns;
        v.push_back(Tick{ts, 1'000'000 + i, 1 + (i & 0xff)});
    }
    return v;
}

// ---------------------------------------------------------------------------
// Path and corpus benchmarks. A fresh aggregate per pass (its construction is
// negligible next to the pass); one clock read per pass, so clock resolution
// does not matter.
// ---------------------------------------------------------------------------
template <std::size_t NBuckets, std::int64_t BucketNs>
static void run_passes(benchmark::State& state, const std::vector<Tick>& ticks) {
    while (state.KeepRunningBatch(static_cast<benchmark::IterationCount>(ticks.size()))) {
        Agg<NBuckets, BucketNs> agg;
        for (const Tick& t : ticks) {
            agg.on_tick(t);
            benchmark::DoNotOptimize(agg.get_sum());
        }
    }
}

template <std::size_t NBuckets>
static void BM_Path(benchmark::State& state) {
    constexpr std::int64_t kBucketNs = 1'000'000;
    const std::vector<Tick> ticks = path_stream(state.range(0), kBucketNs);
    run_passes<NBuckets, kBucketNs>(state, ticks);
}

// Number of corpus ticks on each path, worked out from the timestamps alone.
template <std::size_t NBuckets, std::int64_t BucketNs>
static void add_path_mix(benchmark::State& state, const std::vector<Tick>& ticks) {
    std::int64_t late = 0, same = 0, gap1 = 0, gap_more = 0, silence = 0, last = 0;
    for (const Tick& t : ticks) {
        const std::int64_t bucket = t.ts_ns / BucketNs;
        const std::int64_t gap = bucket - last;
        if (gap < 0) { ++late; continue; }
        if (gap == 0) ++same;
        else if (gap == 1) ++gap1;
        else if (gap <= static_cast<std::int64_t>(NBuckets)) ++gap_more;
        else ++silence;
        last = bucket;
    }
    state.counters["late"]    = static_cast<double>(late);
    state.counters["same"]    = static_cast<double>(same);
    state.counters["gap1"]    = static_cast<double>(gap1);
    state.counters["gap2+"]   = static_cast<double>(gap_more);
    state.counters["silence"] = static_cast<double>(silence);
}

template <std::size_t NBuckets, std::int64_t BucketNs>
static void BM_Corpus(benchmark::State& state) {
    const std::vector<Tick>& ticks = corpus();
    run_passes<NBuckets, BucketNs>(state, ticks);
    add_path_mix<NBuckets, BucketNs>(state, ticks);
}

// ---------------------------------------------------------------------------
// Per-call timing.
// ---------------------------------------------------------------------------
// Clock and histogram: see cycle-clock.hpp.

template <std::size_t NBuckets, std::int64_t BucketNs>
static void BM_PerCall(benchmark::State& state) {
    const std::vector<Tick>& ticks = corpus();
    const ClockInfo& ck = clock_info();
    Histogram hist;

    while (state.KeepRunningBatch(static_cast<benchmark::IterationCount>(ticks.size()))) {
        Agg<NBuckets, BucketNs> agg;
        for (const Tick& t : ticks) {
            const std::uint64_t t0 = clock_begin();
            agg.on_tick(t);
            benchmark::DoNotOptimize(agg.get_sum());
            const std::uint64_t t1 = clock_end();
            hist.add(t1 - t0);
        }
    }

    const auto net_ns = [&ck](std::uint64_t counts) {
        return counts > ck.overhead ? static_cast<double>(counts - ck.overhead) * ck.ns_per_count : 0.0;
    };
    state.counters["p50"]    = net_ns(hist.quantile(0.50));
    state.counters["p99"]    = net_ns(hist.quantile(0.99));
    state.counters["p99.9"]  = net_ns(hist.quantile(0.999));
    state.counters["p99.99"] = net_ns(hist.quantile(0.9999));
    state.counters["max"]    = net_ns(hist.max());
    state.counters["clock_step_ns"]     = ck.step_ns;
    state.counters["timer_overhead_ns"] = static_cast<double>(ck.overhead) * ck.ns_per_count;

    char label[96];
    if (ck.step_ns > 5.0)
        std::snprintf(label, sizeof label, "clock step %.1f ns: percentiles NOT meaningful here", ck.step_ns);
    else
        std::snprintf(label, sizeof label, "clock step %.2f ns", ck.step_ns);
    state.SetLabel(label);
}

// ---------------------------------------------------------------------------
// Registration. Gap -1 = late tick, 0 = same bucket, nbuckets + 1 = long silence.
// ---------------------------------------------------------------------------
BENCHMARK(BM_Path<10>)->Name("RollingSum/path/10buckets")->ArgName("gap")
    ->Arg(-1)->Arg(0)->Arg(1)->Arg(2)->Arg(5)->Arg(10)->Arg(11);
BENCHMARK(BM_Path<64>)->Name("RollingSum/path/64buckets")->ArgName("gap")
    ->Arg(-1)->Arg(0)->Arg(1)->Arg(2)->Arg(4)->Arg(8)->Arg(16)->Arg(32)->Arg(64)->Arg(65);

BENCHMARK(BM_Corpus<10, 1'000'000>)->Name("RollingSum/corpus/10x1ms");
BENCHMARK(BM_Corpus<64, 100'000>)->Name("RollingSum/corpus/64x100us");

BENCHMARK(BM_PerCall<10, 1'000'000>)->Name("RollingSum/percall/10x1ms");
BENCHMARK(BM_PerCall<64, 100'000>)->Name("RollingSum/percall/64x100us");

BENCHMARK_MAIN();
